on. (structure) Contains the configuration settings for a vector index, including the index name, vector attribute, dimensions, distance function, search schema, and projection. IndexName -&gt; (string) [required] The name of the vector index. Constraints: • min: 3 • max: 255 • pattern: [a-zA-Z0-9_.-]+ VectorAttribute -&gt; (structure) [required] The vector attribute configuration for the index. AttributeName -&gt; (string) [required] The name of the vector attribute. Constraints: • min: 1 • max: 255 SearchSchema -&gt; (list) The search schema that defines partition key and inline filter attributes for the vector index. Constraints: • min: 1 (structure) An element in the search schema of a vector index. AttributeName -&gt; (string) [required] The name of the attribute. Constraints: • max: 65535 SearchSchemaElementType -&gt; (string) [required] The role of the attribute in the search schema. Valid values: • HASH - A partition key that partitions the vector index for independent scaling. When specified, you must provide this attribute's value in the SearchConditionExpression . • INLINE_FILTER - An attribute projected into the vector index for filtering at the storage layer during search. Inline filters are optional in the SearchConditionExpression . Possible values: • HASH • INLINE_FILTER Projection -&gt; (structure) [required] Specifies attributes that are copied (projected) from the table into the vector index. ProjectionType -&gt; (string) The set of attributes that are projected into the index: • KEYS_ONLY - Only the index and primary keys are projected into the index. • INCLUDE - In addition to the attributes described in KEYS_ONLY , the secondary index will include other non-key attributes that you specify. • ALL - All of the table attributes are projected into the index. When using the DynamoDB console, ALL is selected by default. Possible values: • ALL • KEYS_ONLY • INCLUDE NonKeyAttributes -&gt; (list) Represents the non-key attribute names which will be projected into the index. For global and local secondary indexes, the total count of NonKeyAttributes summed across all of the secondary indexes, must not exceed 100. If you project the same attribute into two different indexes, this counts as two distinct attributes when determining the total. This limit only applies when you specify the ProjectionType of INCLUDE . You still can specify the ProjectionType of ALL to project all attributes from the source table, even if the table has more than 100 attributes. Constraints: • min: 1 • max: 20 (string) Constraints: • min: 1 • max: 255 Dimensions -&gt; (long) [required] The number of dimensions in each vector. Constraints: • min: 1 DistanceFunction -&gt; (string) [required] The distance function used to calculate similarity between vectors. Valid values: COSINE , EUCLIDEAN , DOT_PRODUCT . Possible values: • COSINE • DOT_PRODUCT • EUCLIDEAN JSON Syntax: { "TableName": "string", "AttributeDefinitions": [ { "AttributeName": "string", "AttributeType": "S"|"N"|"B" } ... ], "KeySchema": [ { "AttributeName": "string", "KeyType": "HASH"|"RANGE" } ... ], "BillingMode": "PROVISIONED"|"PAY_PER_REQUEST", "ProvisionedThroughput": { "ReadCapacityUnits": long, "WriteCapacityUnits": long }, "OnDemandThroughput": { "MaxReadRequestUnits": long, "MaxWriteRequestUnits": long }, "SSESpecification": { "Enabled": true|false, "SSEType": "AES256"|"KMS", "KMSMasterKeyId": "string" }, "GlobalSecondaryIndexes": [ { "IndexName": "string", "KeySchema": [ { "AttributeName": "string", "KeyType": "HASH"|"RANGE" } ... ], "Projection": { "ProjectionType": "ALL"|"KEYS_ONLY"|"INCLUDE", "NonKeyAttributes": ["string", ...] }, "ProvisionedThroughput": { "ReadCapacityUnits": long, "WriteCapacityUnits": long }, "OnDemandThroughput": { "MaxReadRequestUnits": long, "MaxWriteRequestUnits": long }, "WarmThroughput": { "ReadUnitsPerSecond": long, "WriteUnitsPerSecond": long } } ... ], "VectorIndexes": [ { "IndexName": "string", "VectorAttribute": { "AttributeName": "string" }, "SearchSchema": [ { "AttributeName": "string", "SearchSchemaElementType": "HASH"|"INLINE_FILTER" } ... ], "Projection": { "ProjectionType": "ALL"|"KEYS_ONLY"|"INCLUDE", "NonKeyAttributes": ["string", ...] }, "Dimensions": long, "DistanceFunction": "COSINE"|"DOT_PRODUCT"|"EUCLIDEAN" } ... ] }
    /// </summary>
    [CliOption("--table-creation-parameters")]
    public string? TableCreationParameters { get; private init; }

    /// <summary>
    /// Providing a ClientToken makes the call to ImportTableInput idempotent, meaning that multiple identical calls have the same effect as one single call. A client token is valid for 8 hours after the first request that uses it is completed. After 8 hours, any request with the same client token is treated as a new request. Do not resubmit the same request with the same client token for more than 8 hours, or the result might not be idempotent. If you submit a request with the same client token but a change in other parameters within the 8-hour idempotency window, DynamoDB returns an IdempotentParameterMismatch exception. Constraints: • pattern: ^[^\$]+$
    /// </summary>
    [SecretValue]
    [CliOption("--client-token")]
    public string? ClientToken { get; set; }

    /// <summary>
    /// Additional properties that specify how the input is formatted, Csv -&gt; (structure) The options for imported source files in CSV format. The values are Delimiter and HeaderList. Delimiter -&gt; (string) The delimiter used for separating items in the CSV file being imported. Constraints: • min: 1 • max: 1 • pattern: [,;:|\t ] HeaderList -&gt; (list) List of the headers used to specify a common header for all source CSV files being imported. If this field is specified then the first line of each CSV file is treated as data instead of the header. If this field is not specified the the first line of each CSV file is treated as the header. Constraints: • min: 1 • max: 255 (string) Constraints: • min: 1 • max: 65536 • pattern: [\x20-\x21\x23-\x2B\x2D-\x7E]* Shorthand Syntax: Csv={Delimiter=string,HeaderList=[string,string]} JSON Syntax: { "Csv": { "Delimiter": "string", "HeaderList": ["string", ...] } }
    /// </summary>
    [CliOption("--input-format-options")]
    public string? InputFormatOptions { get; set; }

    /// <summary>
    /// Type of compression to be used on the input coming from the imported table. Possible values: • GZIP • ZSTD • NONE
    /// </summary>
    [CliOption("--input-compression-type")]
    public AwsDynamodbImportTableInputCompressionType? InputCompressionType { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

    /// <summary>Appends diagnostic members without exposing command option values.</summary>
    /// <param name="builder">The builder receiving the record members.</param>
    /// <returns>True because a redaction marker was appended.</returns>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
        builder.Append("Options = <redacted>");
        return true;
    }

